#!/usr/bin/env python3
import hashlib,json,sqlite3
from pathlib import Path
HERE=Path(__file__).resolve().parents[1]
RESULT=HERE/'RESULT.json';AUDIT=HERE/'AUDIT.json'
if AUDIT.exists(): raise SystemExit('audit exists; overwrite forbidden')
data=json.loads(RESULT.read_text());rows=data['rows'];errors=[]
if len(rows)!=12: errors.append('row_count')
if data.get('formal_invocations')!=1 or data.get('formal_reruns')!=0: errors.append('rerun_accounting')
for row in rows:
    cid=row['case_id'];case_dir=HERE/'results'/'formal'/cid;db=case_dir/'owner.sqlite'
    conn=sqlite3.connect(db)
    try:
        rr=conn.execute('SELECT command_id,invariant_manifest_id,effect_seq,effect_value FROM receipts').fetchall()
        ec=conn.execute("SELECT COUNT(*) FROM events WHERE kind='effect'").fetchone()[0]
    finally: conn.close()
    if len(rr)!=1 or ec!=1: errors.append(cid+':owner_count');continue
    command,manifest,seq,value=rr[0]
    n=row['nested_receipt'] or {}
    if row['status']!='boundary': errors.append(cid+':outer_boundary')
    if row.get('socket_authority')!='none': errors.append(cid+':authority')
    if row['record_count']!=1 or row['effect_count']!=1: errors.append(cid+':counts')
    if n.get('command_id')!=command or n.get('effect_seq')!=seq or n.get('effect_value')!=value: errors.append(cid+':semantic_transport')
    if row['mode']=='exact_receipt':
        if n.get('invariant_manifest_id')!=manifest or not row['caller_owner_verified']: errors.append(cid+':exact_verify')
    else:
        if n.get('invariant_manifest_id')==manifest or row['caller_owner_verified']: errors.append(cid+':forged_escape')
# exact cells: 3 each mode/scope
from collections import Counter
cells=Counter((r['mode'],r['scope']) for r in rows)
if any(cells[(m,s)]!=3 for m in ('exact_receipt','forged_manifest') for s in ('action','request')):errors.append('cell_counts')
decision='PASS_EFFECT_OWNER_SOCKET_PATH_SCOPED' if not errors else ('FAIL_RECEIPT_PROVENANCE_ESCAPE' if any('forged_escape' in e for e in errors) else 'FAIL_SOCKET_RECEIPT_TRANSPORT')
out={'schema':'effect-owner-socket-path-audit-v1','decision':decision,'errors':errors,'cells':{f'{m}:{s}':cells[(m,s)] for m in ('exact_receipt','forged_manifest') for s in ('action','request')},'result_sha256':hashlib.sha256(RESULT.read_bytes()).hexdigest()}
AUDIT.write_text(json.dumps(out,indent=2,sort_keys=True)+'\n');print(decision,errors)

