import json, shutil, tempfile, unittest
from pathlib import Path
from run_case import run_case

class Contract(unittest.TestCase):
    def test_excluded_exact_action(self):
        with tempfile.TemporaryDirectory() as d:
            r=run_case(Path(d)/'x','construction-exact','exact_receipt','action')
            self.assertEqual(r['status'],'boundary');self.assertTrue(r['caller_owner_verified']);self.assertEqual(r['effect_count'],1)
    def test_excluded_forged_request(self):
        with tempfile.TemporaryDirectory() as d:
            r=run_case(Path(d)/'x','construction-forged','forged_manifest','request')
            self.assertEqual(r['status'],'boundary');self.assertFalse(r['caller_owner_verified']);self.assertEqual(r['effect_count'],1)

if __name__=='__main__':unittest.main()
